-- DEV-001: consented endpoints and atomic event-time outbox. No historical backfill.
CREATE TABLE nc_webhook_endpoints(id TEXT PRIMARY KEY,url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),secret_sealed TEXT NOT NULL,previous_sealed TEXT,overlap_until INTEGER,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE nc_webhook_events(id TEXT PRIMARY KEY,type TEXT NOT NULL,customer_id TEXT,subject TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at INTEGER NOT NULL);
CREATE TABLE nc_webhook_deliveries(id TEXT PRIMARY KEY,endpoint_id TEXT NOT NULL REFERENCES nc_webhook_endpoints(id),event_id TEXT NOT NULL REFERENCES nc_webhook_events(id),customer_id TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','delivered','exhausted','suppressed')),attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,deadline INTEGER NOT NULL,claim TEXT,http_status INTEGER,updated_at INTEGER NOT NULL,UNIQUE(endpoint_id,event_id));
CREATE INDEX nc_webhook_due ON nc_webhook_deliveries(status,next_at);
CREATE TABLE nc_webhook_attempts(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES nc_webhook_deliveries(id),customer_id TEXT,attempt INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('accepted','refused','uncertain')),http_status INTEGER,at INTEGER NOT NULL,UNIQUE(delivery_id,attempt));
CREATE TRIGGER nc_webhook_enqueue AFTER INSERT ON nc_webhook_events BEGIN
 INSERT INTO nc_webhook_deliveries(id,endpoint_id,event_id,customer_id,next_at,deadline,updated_at)
 SELECT lower(hex(randomblob(16))),id,NEW.id,NEW.customer_id,NEW.created_at,NEW.created_at+259200000,NEW.created_at FROM nc_webhook_endpoints WHERE enabled=1;
END;
ALTER TABLE nc_notification_preferences ADD COLUMN webhook_failure INTEGER NOT NULL DEFAULT 0 CHECK(webhook_failure IN (0,1));
DROP TRIGGER nc_notifications_content;
DROP TRIGGER nc_notifications_keep;
ALTER TABLE nc_notifications RENAME TO nc_notifications_old;
CREATE TABLE nc_notifications(event TEXT NOT NULL CHECK(event IN ('payment_mismatch','billrun_exceptions','proposals','webhook_failure')),subject TEXT NOT NULL,href TEXT NOT NULL,member_id TEXT NOT NULL REFERENCES nc_members(id),email TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','sending','accepted','suppressed','failed','rejected','uncertain')),provider_ref TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(event,subject,member_id));
INSERT INTO nc_notifications SELECT * FROM nc_notifications_old;
DROP TABLE nc_notifications_old;
CREATE TRIGGER nc_notifications_content BEFORE UPDATE OF event,subject,href,member_id,email ON nc_notifications WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_notifications_keep BEFORE DELETE ON nc_notifications WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_customer_created AFTER INSERT ON nc_customers
 WHEN (1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.id AND erased_at IS NOT NULL)
 BEGIN
 INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 VALUES(lower(hex(randomblob(16))),'customer.created',NEW.id,NEW.id,json_object('type','customer.created','data',json_object('id',NEW.id,'customer_id',NEW.id,'subscription_id',NULL,'invoice_id',NULL,'payment_id',NULL,'credit_note_id',NULL,'status',NULL), 'metadata',json_array(json_object('kind','customer','id',NEW.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',c.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=c.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes c WHERE c.invoice_id=NULL),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN (SELECT price_id FROM nc_items WHERE subscription_id=NULL UNION SELECT price_id FRO