CREATE TRIGGER nc_webhook_invoice_paid AFTER INSERT ON nc_allocations
 WHEN ((SELECT total_cents FROM nc_invoices WHERE id=NEW.invoice_id AND status='issued')=COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=NEW.invoice_id),0)+COALESCE((SELECT SUM(amount_cents) FROM nc_credit_notes WHERE invoice_id=NEW.invoice_id),0)) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=(SELECT customer_id FROM nc_invoices WHERE id=NEW.invoice_id) AND erased_at IS NOT NULL)
 BEGIN
 INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 VALUES(lower(hex(randomblob(16))),'invoice.paid',(SELECT customer_id FROM nc_invoices WHERE id=NEW.invoice_id),NEW.invoice_id,json_object('type','invoice.paid','data',json_object('id',NEW.invoice_id,'customer_id',(SELECT customer_id FROM nc_invoices WHERE id=NEW.invoice_id),'subscription_id',(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id),'invoice_id',NEW.invoice_id,'payment_id',NEW.payment_id,'credit_note_id',NULL,'amount_cents',(SELECT total_cents FROM nc_invoices WHERE id=NEW.invoice_id)), 'metadata',json_array(json_object('kind','customer','id',(SELECT customer_id FROM nc_invoices WHERE id=NEW.invoice_id),'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=(SELECT customer_id FROM nc_invoices WHERE id=NEW.invoice_id) ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id),'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NEW.invoice_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.invoice_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NEW.payment_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NEW.payment_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',c.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=c.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes c WHERE c.invoice_id=NEW.invoice_id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN (SELECT price_id FROM nc_items WHERE subscription_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NEW.invoice_id AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER));
 END;
