CREATE TRIGGER nc_webhook_events_immutable BEFORE UPDATE OF id,type,customer_id,subject,payload_json,created_at ON nc_webhook_events WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_attempts_immutable BEFORE UPDATE OF id,delivery_id,customer_id,attempt,status,http_status,at ON nc_webhook_attempts WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
